'use strict';
const {Game,LEVELS,FOODS,normalizeLevel}=SnackGame;
const $=id=>document.getElementById(id),params=new URLSearchParams(location.search);
const TEST_MODE=['localhost','127.0.0.1',''].includes(location.hostname)&&params.get('mode')!=='production';
const STORAGE_KEY=TEST_MODE?'snack-progress-test-v2':'snack-progress-prod-v2',ads=new SnackAds.AdGateway();
const FOOD_NAMES=FOODS.map((n,i)=>i===8?'蛋散':n);
// Figma sprite crops: x, y, width, height, image width/height/left/top percentages.
const FOOD_ART=[[7,6,38,35,368.26,417.65,-16.77,-11.11],[6,5,40,38,354.47,405.71,-239.19,-9.84],[7,7,40,35,342.62,405.71,-119.22,-106.98],[6.15,5.1,40,38,376.15,407.01,-133.33,-9.55],[6,7,40,33,336.99,414.94,-223.56,-114.94],[8,6,36,37,407.28,412.26,-21.85,-111.61],[6,7,40,33,355.12,143.48,-10.07,-21.21],[6,7,40,33,355.12,143.48,-127.57,-21.21],[6,7,40,33,355.12,143.48,-245.07,-21.21]];
function art(type,blocked=false,scale){const a=FOOD_ART[type],style=scale===undefined?'':` style="transform:scale(${scale})"`;const food=a?`<span class="food-window" style="left:${a[0]}px;top:${a[1]}px;width:${a[2]}px;height:${a[3]}px"><img alt="" src="assets/${type>=6?'food-extra':'food-sheet'}.png" style="width:${a[4]}%;height:${a[5]}%;left:${a[6]}%;top:${a[7]}%"></span>`:`<span class="food-fallback">${FOOD_NAMES[type]}</span>`;return `<span class="card-art" aria-hidden="true"${style}><span class="card-base"></span><span class="card-face"></span>${food}${blocked?'<span class="card-mask"></span>':''}</span>`;}
let saved={level:1,completed:[]};try{const raw=localStorage.getItem(STORAGE_KEY)||(TEST_MODE?localStorage.getItem('snack-progress-v1'):null),d=JSON.parse(raw||'{}');if(d&&typeof d==='object'&&!Array.isArray(d)){saved.completed=Array.isArray(d.completed)?[...new Set(d.completed.filter(n=>Number.isInteger(n)&&n>=1&&n<=LEVELS.length))]:[];saved.level=normalizeLevel(d.level);}}catch{}
